import React, { useState } from 'react';
import { useNavigate, Link } from 'react-router-dom'; // <- make sure useNavigate is imported

export default function Login() {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const navigate = useNavigate(); // <- correct hook usage

  function handleSubmit(e) {
    e.preventDefault();
    const usersJson = localStorage.getItem('users');
    const users = usersJson ? JSON.parse(usersJson) : [];
    const found = users.find(u => u.email === email && u.password === password);
    if (!found) {
      setError('Invalid email or password. Or sign up first.');
      return;
    }
    const token = btoa(email + ':' + Date.now());
    localStorage.setItem('authToken', token);
    localStorage.setItem('currentUser', JSON.stringify({ email }));
    navigate('/'); // navigate to dashboard
  }

  return (
    <div style={{maxWidth:480, margin:'40px auto', padding:20}}>
      <h2>Login</h2>
      <form onSubmit={handleSubmit}>
        <div>
          <label>Email</label>
          <input value={email} onChange={e => setEmail(e.target.value)} required type="email" />
        </div>
        <div style={{marginTop:8}}>
          <label>Password</label>
          <input value={password} onChange={e => setPassword(e.target.value)} required type="password" />
        </div>
        {error && <div style={{color:'red',marginTop:8}}>{error}</div>}
        <div style={{marginTop:12}}>
          <button type="submit">Log in</button>
        </div>
      </form>
      <p style={{marginTop:12}}>Don't have an account? <Link to="/signup">Sign up</Link></p>
    </div>
  );
}
